import { useState } from 'react';
import { Badge, Band, DataTable, DateText, Drawer, Field, Filters, Form, LookupSelect, NumberInput, Num, Pager, Pairs, RefName, Select, TextInput, Tiles, call, useData } from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

export default function FnSfr04003Page({ role, notify }: PageProps) {
  const [messageType, setMessageType] = useState('MAIL');
  const [userName, setUserName] = useState('');
  const [query, setQuery] = useState<Row>({ messageType: 'MAIL', userName: '' });
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [composing, setComposing] = useState(false);
  const [recipients, setRecipients] = useState<number[]>([]);
  const [pick, setPick] = useState<number | string>('');
  const [subject, setSubject] = useState('');
  const [content, setContent] = useState('');
  const [attachmentRef, setAttachmentRef] = useState('');
  const [targetType, setTargetType] = useState('');
  const [targetId, setTargetId] = useState<number | string>('');

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/messages', role, undefined, { ...query, page, size: SIZE }),
    [role, query, page],
  );

  function search() {
    setPage(0);
    setQuery({ messageType, userName });
  }

  function reset() {
    setMessageType('MAIL');
    setUserName('');
    setPage(0);
    setQuery({ messageType: 'MAIL', userName: '' });
  }

  function openCompose() {
    setRecipients([]);
    setPick('');
    setSubject('');
    setContent('');
    setAttachmentRef('');
    setTargetType('');
    setTargetId('');
    setComposing(true);
  }

  function addRecipient() {
    if (pick === '' || typeof pick !== 'number') return;
    if (recipients.includes(pick)) return;
    setRecipients([...recipients, pick]);
    setPick('');
  }

  async function send() {
    if (recipients.length === 0) {
      throw new Error('받는 사람을 한 명 이상 선택하세요.');
    }
    if (targetType.trim() === '' || targetId === '') {
      throw new Error('연계 대상 업무 항목 유형과 ID를 입력하세요.');
    }
    await call('POST', '/messages', role, {
      messageType: 'MAIL',
      subject,
      content,
      attachmentRef,
      recipientIds: recipients,
      targetType,
      targetId,
    });
    notify('메일을 발송했습니다.');
    setComposing(false);
    reload();
  }

  const rows = data ? data.items : [];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>받은편지함 현황</h2>
        <Tiles items={[['조회 건수', <Num value={data ? data.total : 0} />]]} />
      </section>

      <section className="box span-12">
        <h2>받은편지함</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="메시지 유형">
            <Select
              value={messageType}
              onChange={setMessageType}
              options={[['MAIL', '전자우편'], ['CHAT', '메신저'], ['NOTE', '쪽지']]}
              placeholder="전체"
            />
          </Field>
          <Field label="성명">
            <TextInput value={userName} onChange={setUserName} />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={openCompose}>메일 작성</button>
        </Band>
        {error ? <p>{error}</p> : null}
        {loading && !data ? <p>불러오는 중입니다.</p> : null}
        <DataTable
          columns={[
            { key: 'messageType', label: '메시지 유형', render: (r) => <Badge value={r.messageType} /> },
            { key: 'subject', label: '제목' },
            { key: 'senderName', label: '성명' },
            { key: 'sentAt', label: '발송 일시', render: (r) => <DateText value={r.sentAt} time /> },
          ]}
          rows={rows}
          onRowClick={(r) => setDetail(r)}
          empty="받은 메일이 없습니다."
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>

      {detail ? (
        <Drawer title="메일 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['메시지 유형', <Badge value={detail.messageType} />],
              ['제목', String(detail.subject ?? '')],
              ['성명', String(detail.senderName ?? '')],
              ['발송 일시', <DateText value={detail.sentAt} time />],
              ['메시지 내용', String(detail.content ?? '')],
            ]}
          />
        </Drawer>
      ) : null}

      {composing ? (
        <Drawer title="메일 작성" onClose={() => setComposing(false)}>
          <Form onSubmit={send} submit="발송">
            <Field label="수신 임직원 ID 목록" required wide hint="임직원을 고른 뒤 추가를 누르세요.">
              <LookupSelect table="employee" role={role} value={pick} onChange={setPick} placeholder="임직원 선택" />
              <button type="button" onClick={addRecipient}>추가</button>
              <ul>
                {recipients.map((id) => (
                  <li key={id}>
                    <RefName table="employee" role={role} value={id} />
                    <button type="button" onClick={() => setRecipients(recipients.filter((x) => x !== id))}>삭제</button>
                  </li>
                ))}
              </ul>
            </Field>
            <Field label="제목" wide>
              <TextInput value={subject} onChange={setSubject} />
            </Field>
            <Field label="메시지 내용" wide>
              <TextInput value={content} onChange={setContent} multiline />
            </Field>
            <Field label="첨부파일 연결" wide>
              <TextInput value={attachmentRef} onChange={setAttachmentRef} />
            </Field>
            <Field label="연계 대상 업무 항목 유형" required>
              <TextInput value={targetType} onChange={setTargetType} />
            </Field>
            <Field label="연계 대상 업무 항목 ID" required>
              <NumberInput value={targetId} onChange={setTargetId} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
